let scopedOrders=()=>{if(state.role==='client')return [orders[0]];if(state.role==='sales')return orders.filter(o=>o.owner==='周敏');if(state.role==='custom'){const account=mockData.accounts.find(a=>a.id===state.activeMockAccountId)||mockData.accounts.find(a=>a.id==='acct-custom-xu');const scopes=account?.dataScopes||[];return orders.filter(o=>scopes.includes(o.group))}return orders};
