function pendingTaskCount(){const tasks=globalThis.__autoflowBadgeTasks;if(!Array.isArray(tasks))return 0;return tasks.filter(task=>task.status==='待处理'&&canSeeTask(task)).length}
function refreshTaskBadge(){const badge=document.querySelector('#navigation .nav-item[data-view="tasks"] .badge');if(!badge)return;const count=pendingTaskCount();badge.textContent=count;badge.hidden=count===0;badge.setAttribute('aria-label',`${count} 项待处理待办`)}
function nav(){const p=people[state.role],pendingCount=pendingTaskCount();document.querySelector('#navigation').innerHTML=p.nav.map((x,i)=>`${i===0||x==='organization'?`<p class="nav-label">${i===0?'业务总览':'系统管理'}</p>`:''}<button class="nav-item ${x==='dashboard'?'active':''}" data-view="${x}"><span class="icon">${labels[x][1]}</span>${labels[x][0]}${x==='tasks'?`<b class="badge" aria-label="${pendingCount} 项待处理待办" ${pendingCount?'':'hidden'}>${pendingCount}</b>`:''}</button>`).join('');document.querySelector('#account-name').textContent=p.name;document.querySelector('#account-role').textContent=p.title;document.querySelector('.initial').textContent=p.name[0]}
function layout(title,subtitle,button=''){return `<div class="heading"><div><p class="eyebrow">${title.toUpperCase()}</p><h1>${title}</h1><p>${subtitle}</p></div>${button}</div>`}
function orderRows(rows=orders){return rows.map(o=>`<tr><td><strong>${o.id}</strong></td><td><strong>${o.customer}</strong><br><small>${o.company}</small></td><td>${o.car}</td><td>${o.type}</td>${state.role==='client'?'':`<td>${o.owner}</td>`}<td>${tag(o.stage)}</td><td class="money">${money(o.total)}</td><td>${o.updated}</td><td><button class="text-button" data-action="order-detail" data-id="${o.id}">查看 →</button></td></tr>`).join('')}
function dashboard(){const client=state.role==='client';document.querySelector('#dashboard').innerHTML=layout(client?'我的订单':'工作台',client?'查看你的报价、付款与交付动态。':'早上好，'+people[state.role].name+'。这里是今天需要关注的业务动态。',client?'':`<button class="primary" data-action="new-order">＋ 新建订单</button>`)+`<div class="stats"><article class="card stat"><div class="stat-head"><span>${client?'进行中订单':'活跃订单'}</span><i class="stat-icon t-green">◫</i></div><strong>${client?'1':'48'}</strong><p>${client?'包含 1 笔待跟进报价':'<span class="up">+8.2%</span> 较上周'}</p></article><article class="card stat"><div class="stat-head"><span>${client?'待付款金额':'本月预计回款'}</span><i class="stat-icon t-purple">¥</i></div><strong>${client?'$ 76,000':'¥ 286.4'}<small>${client?' USD':' 万'}</small></strong><p>${client?'定金已确认，等待尾款':'<span class="up">+12.6%</span> 较上月'}</p></article><article class="card stat"><div class="stat-head"><span>${client?'待处理事项':'待跟进客户'}</span><i class="stat-icon t-orange">◷</i></div><strong>${client?'2':'16'}</strong><p>${client?'请上传付款凭证 / 确认报价':'其中 5 位超过 3 天未跟进'}</p></article><article class="card stat"><div class="stat-head"><span>${client?'当地时间':'成交转化率'}</span><i class="stat-icon t-blue">◎</i></div><strong>${client?'<span id="big-dubai">--:--</span>':'31.4'}${client?'':'<small>%</small>'}</strong><p>${client?'Dubai · UTC+4':'<span class="up">+2.1%</span> 较上月'}</p></article></div>`+(client?clientDashboard():adminDashboard())}
function adminDashboard(){return `<div class="grid-2"><section class="panel"><div class="panel-head"><div><h2>订单销售漏斗</h2><p>按当前订单阶段统计</p></div><button class="text-button">本月⌄</button></div>${[['初步交涉',92,'18','37.5%'],['发送报价',74,'14','29.2%'],['报价待跟进',55,'9','18.8%'],['定金确认',34,'5','10.4%'],['FOB 完成',15,'2','4.1%']].map(r=>`<div class="funnel-row"><span>${r[0]}</span><div class="funnel-track"><b style="width:${r[1]}%"></b></div><strong>${r[2]}</strong><small>${r[3]}</small></div>`).join('')}</section><section class="panel"><div class="panel-head"><div><h2>优先待办</h2><p>系统自动生成与人工创建</p></div><button class="text-button" data-view="tasks">全部 6 →</button></div><div class="todo"><span class="todo-mark t-orange">¥</span><div><strong>2 笔付款凭证等待审核</strong><p>客户已上传银行回单</p></div><button data-view="payments">处理</button></div><div class="todo"><span class="todo-mark" style="background:#fee9e6;color:#d27169">!</span><div><strong>5 位客户超过 3 天未跟进</strong><p>建议在当地工作时段联系</p></div><button data-view="tasks">查看</button></div><div class="todo"><span class="todo-mark t-purple">↗</span><div><strong>销售账号离职交接待处理</strong><p>9 位客户尚未重新分配</p></div><button data-view="organization">交接</button></div></section></div><section class="panel"><div class="panel-head"><div><h2>最近订单</h2><p>销售团队的最新业务更新</p></div><button class="text-button" data-view="orders">订单中心 →</button></div><div class="table-wrap"><table><thead><tr><th>订单编号</th><th>客户</th><th>商品</th><th>订单类型</th><th>负责人</th><th>阶段</th><th>对客总价</th><th>更新时间</th><th></th></tr></thead><tbody>${orderRows(scopedOrders().slice(0,4))}</tbody></table></div></section>`}
function clientDashboard(){const o=orders[0];return `<section class="panel"><div class="panel-head"><div><h2>订单进度</h2><p>${o.id} · ${o.car}</p></div>${tag(o.stage)}</div><div class="funnel-row" style="grid-template-columns:1fr"><div class="funnel-track"><b style="width:54%"></b></div></div><div class="profile-meta"><div><small>对客报价</small><b>USD 76,000</b></div><div><small>付款状态</small><b>已付定金</b></div><div><small>下一事项</small><b>上传尾款凭证</b></div></div><button class="primary" data-action="upload-proof">上传付款凭证</button></section><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>报价明细</h2><button class="text-button" data-action="order-detail" data-id="AF-2026-0088">查看订单 →</button></div><div class="table-wrap"><table><thead><tr><th>商品</th><th>数量</th><th>对客单价</th><th>小计</th></tr></thead><tbody><tr><td>吉利 博越L 2025款</td><td>1</td><td>USD 74,800</td><td>USD 74,800</td></tr><tr><td>前大灯总成</td><td>2</td><td>USD 600</td><td>USD 1,200</td></tr></tbody></table></div></section>`}
function ordersView(){document.querySelector('#orders').innerHTML=layout('订单中心','跟踪整车、配件和混合订单的报价、收款与交付。',state.role==='client'?'':`<button class="primary" data-action="new-order">＋ 新建订单</button>`)+`${state.role==='client'?'<div class="client-note">以下仅展示已授权订单的对客报价、付款与交付信息。</div>':''}<div class="filter-bar"><label>⌕ <input id="search-orders" placeholder="搜索订单号、客户或商品" /></label><select id="stage-select"><option value="">全部阶段</option>${Object.keys(tagClass).map(x=>`<option>${x}</option>`).join('')}</select><button class="secondary">筛选</button></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>订单编号</th><th>客户</th><th>商品</th><th>业务类型</th>${state.role==='client'?'':`<th>负责人</th>`}<th>阶段</th><th>对客总价</th><th>最后更新</th><th></th></tr></thead><tbody id="orders-body">${orderRows(scopedOrders())}</tbody></table></div></section>`;document.querySelector('#search-orders').oninput=filterOrders;document.querySelector('#stage-select').onchange=filterOrders}
function filterOrders(){const q=document.querySelector('#search-orders').value.toLowerCase(),stage=document.querySelector('#stage-select').value;const list=scopedOrders().filter(o=>(`${o.id}${o.customer}${o.car}`).toLowerCase().includes(q)&&(!stage||o.stage===stage));document.querySelector('#orders-body').innerHTML=orderRows(list)}
function customersView(){if(state.role==='client'){showView('dashboard');return}const list=visibleCustomers();if(!list.includes(customers[state.customer]))state.customer=customers.indexOf(list[0]);document.querySelector('#customers').innerHTML=layout('客户管理','销售提交客户资料与账号申请，团队管理员审核后启用。',`<button class="primary" data-action="new-customer">＋ 新建客户</button>`)+`<div class="customer-layout"><section class="panel customer-list"><div class="panel-head"><h2>客户列表</h2><span class="tag contact">${state.role==='sales'?list.length:'36'} 位</span></div><div id="customer-list"></div></section><section class="panel customer-detail" id="customer-detail"></section></div>`;renderCustomerList();showCustomer(state.customer)}
function renderCustomerList(){document.querySelector('#customer-list').innerHTML=visibleCustomers().map(c=>{const i=customers.indexOf(c);return `<button class="customer-item ${i===state.customer?'active':''}" data-customer="${i}"><span class="customer-avatar">${c.name[0]}</span><span><strong>${c.name}</strong><small>${c.company} · ${c.owner}</small></span></button>`}).join('')}
function showCustomer(i){state.customer=i;const c=customers[i];document.querySelectorAll('.customer-item').forEach((x,n)=>x.classList.toggle('active',n===i));const os=orders.filter(o=>c.orders.includes(o.id));const contacts=c.contacts.map(x=>`<span class="contact-chip"><b>${x[0]}</b>${x[1]}</span>`).join('');document.querySelector('#customer-detail').innerHTML=`<div class="customer-profile"><span class="customer-avatar">${c.name[0]}</span><div><h2>${c.name}</h2><p>${c.company} · ${c.type} · 负责人：${c.owner}</p></div><button class="secondary" data-action="new-order">＋ 新建订单</button></div><div class="profile-meta"><div><small>客户类型</small><b>${c.type}</b></div><div><small>所在市场 / 时区</small><b>${c.country}<br>${c.zone}</b></div><div><small>联系方式</small><div class="contact-chips">${contacts}</div></div></div><div class="section-line"><h3>备注</h3><p class="customer-note">${c.note}</p></div><div class="section-line"><h3>关联订单 · ${os.length}</h3>${os.map(o=>`<div class="mini-order"><div><strong>${o.id} · ${o.car}</strong><p>报价总额：${money(o.total)} · 更新：${o.updated}</p></div>${tag(o.stage)}</div>`).join('')}</div><div class="section-line"><h3>账号审核状态</h3><p style="font-size:11px;color:#718088">客户资料已完整，账号已启用。客户仅可查看被授权订单、对客报价、付款与交付进度。</p></div>`}
