function piText(key,label){return `<label class="pi-field pi-full"><span>${label}</span><textarea data-pi="${key}">${piState[key]??''}</textarea></label>`}
function piEditor(){const s=piState;const tabs=[['basic','基本信息'],['parties','交易双方'],['items','产品明细'],['terms','贸易与交付'],['bank','条款与签章']];let content='';if(state.piTab==='basic')content=`<div class="pi-grid">${piInput('documentNo','单据编号 / Document No.')}${piInput('date','日期 / Date','date')}${piInput('reference','关联编号 / Reference')}${piInput('currency','币种 / Currency')}${piInput('validUntil','有效期 / Valid Until','date')}<label class="pi-field"><span>目的地 / Destination</span><input data-pi="destination" value="${s.destination}" /></label></div>`;if(state.piTab==='parties')content=`<div class="pi-grid pi-party-grid">${piInput('seller','卖方 / Seller')}${piInput('buyer','买方 / Buyer')}${piText('sellerAddress','卖方地址 / Seller Address')}${piText('buyerAddress','买方地址 / Buyer Address')}${piInput('contact','买方联系人 / Buyer Contact')}</div>`;if(state.piTab==='items')content=`<div class="pi-item-editor"><div class="pi-item-head"><span>产品 / Item</span><span>规格 / Specification</span><span>数量</span><span>单位</span><span>单价</span></div>${s.items.map((x,i)=>`<div class="pi-item-row"><input data-pi-item="name" data-index="${i}" value="${x.name}" /><input data-pi-item="spec" data-index="${i}" value="${x.spec}" /><input data-pi-item="qty" data-index="${i}" type="number" value="${x.qty}" /><input data-pi-item="unit" data-index="${i}" value="${x.unit}" /><input data-pi-item="price" data-index="${i}" type="number" value="${x.price}" /></div>`).join('')}<button type="button" class="pi-add" data-action="add-pi-item">＋ 添加产品 / Add Item</button></div>`;if(state.piTab==='terms')content=`<div class="pi-grid">${piInput('incoterm','贸易术语 / Incoterm')}${piInput('place','指定地点 / Named Place')}${piInput('delivery','交付时间 / Delivery')}${piInput('packaging','包装方式 / Packaging')}${piInput('origin','原产国 / Country of Origin')}${piText('payment','付款方式 / Payment Terms')}</div>`;if(state.piTab==='bank')content=`<div class="pi-grid">${piText('bank','银行信息 / Bank Details')}${piText('notes','备注 / Notes')}</div>`;return `<div class="pi-editor"><div class="pi-tabs">${tabs.map(x=>`<button class="pi-tab ${state.piTab===x[0]?'active':''}" data-action="pi-tab" data-tab="${x[0]}">${x[1]}</button>`).join('')}</div><div class="pi-form-head"><div><p>PI WORKSPACE</p><h2>${tabs.find(x=>x[0]===state.piTab)[1]}</h2></div><span>用于订单确认、付款及进口许可</span></div>${content}</div>`}
