function applyAccountFormRules(form,policy=creatorPolicy()){
 const type=form.elements.accountType.value,groupSelect=form.elements.group,standard=['普通销售','业务分组组长'].includes(type);
 if(type==='跨业务团队'&&policy.allowCross)groupSelect.value='跨团队';
 if(standard&&(!policy.groups.includes(groupSelect.value)))groupSelect.value=policy.groups[0]||'';
 const activeGroup=groupSelect.value,cross=type==='跨业务团队';
 groupSelect.disabled=cross||policy.groups.length<=1;
 const allowedModules=policy.account?.modules||['CRM','库存','发票'];
 Array.from(form.querySelectorAll('[name="modules"]')).forEach(input=>{const permitted=allowedModules.includes(input.value);input.disabled=!permitted;if(!permitted)input.checked=false;else if(!input.checked&&standard&&['CRM','库存'].includes(input.value))input.checked=true});
 Array.from(form.querySelectorAll('[name="scopes"]')).forEach(input=>{const permitted=policy.groups.includes(input.value);input.disabled=!cross||!permitted;if(cross)input.checked=permitted&&input.checked;else input.checked=input.value===activeGroup});
 form.querySelector('#scope-hint').textContent=cross?'跨团队账号可选择零个、一个或多个业务团队的数据范围；未选择时无法查看任何团队数据。':activeGroup?`所属业务分组为“${activeGroup}”，数据访问范围已锁定为该团队。`:'当前账号没有区域信息查看权；创建的子账号将不具备任何区域数据访问范围。'
}
