// Explicit super-admin creation path: it never inherits a child-team scope restriction.
createMockAccount=function(form){
 const data=new FormData(form),accountType=form.elements.accountType.value,group=form.elements.group.value;
 const allGroups=['华东团队','华南团队','华北团队'];
 const isSuper=state.role==='super'&&activeAccount()?.accountType==='超管';
 const policy=creatorPolicy();
 if(!isSuper&&(!policy.canCreate||!policy.allowedTypes.includes(accountType))){creationScopeError();return}
 if(isSuper&&!['跨业务团队','业务分组组长','普通销售'].includes(accountType)){creationScopeError();return}
 const modules=Array.from(form.querySelectorAll('[name="modules"]:checked')).map(item=>item.value);
 const submittedScopes=Array.from(form.querySelectorAll('[name="scopes"]:checked')).map(item=>item.value);
 if(!modules.length){toast('请至少选择一个功能模块。');return}
 const parentModules=isSuper?['CRM','库存','发票']:policy.account?.modules||[];
 if(modules.some(module=>!parentModules.includes(module))){toast('权限范围异常：子账号的功能模块不能超出父级账号权限。');return}
 if(accountType==='跨业务团队'){
  if(group!=='跨团队'||submittedScopes.some(scope=>!allGroups.includes(scope))){creationScopeError();return}
 }else{
  const permittedGroups=isSuper?allGroups:policy.groups;
  if(permittedGroups.length?!permittedGroups.includes(group):group!==''){creationScopeError();return}
 }
 const account={id:`acct-${Date.now()}`,name:data.get('name')||'未命名账号',accountType,group,email:data.get('email')||'未填写邮箱',modules,dataScopes:accountType==='跨业务团队'?submittedScopes:(group?[group]:[]),status:'正常'};
 mockData.accounts.push(account);persistMockData();refreshAccountSwitcher();closeModal();toast(`账号“${account.name}”已创建并写入 Mock 数据`);organizationView()
};

